<div class="page-head"><div><p class="eyebrow">Purchase</p><h1>Purchase Processing</h1><p>Record purchases; completed purchases automatically increase stock.</p></div></div><section class="panel"><div class="panel-head"><h2>Create Purchase</h2></div><form method="post" data-validate-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Supplier</label><select name="supplier_id"><option value="0">— Select supplier —</option><?php foreach($suppliers as $s): ?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach; ?></select></div><div class="field"><label>Product</label><select name="product_id" id="purchaseProduct" required><?php foreach($products as $p): ?><option value="<?=$p['id']?>"><?=e($p['name'])?> (<?=e($p['sku'])?>) — Stock <?=e($p['quantity'])?></option><?php endforeach; ?></select></div><div class="field full"><label>Quick Product Search (AJAX/JSON)</label><input class="role-product-search" type="search" data-results="#roleSearchResults" placeholder="Type product name or SKU..."><div id="roleSearchResults" class="ajax-results" aria-live="polite"></div></div><div class="field"><label>Quantity</label><input type="number" name="quantity" min="1" required></div><div class="field"><label>Purchase Price / Unit (৳)</label><input type="number" name="unit_price" min="0" step="0.01" required></div></div><div class="form-actions"><button class="btn role-btn">✓ Complete Purchase</button></div></form></section><br><section class="panel"><div class="panel-head"><div><h2>Purchase History</h2><span class="panel-sub">Search and review previous purchase transactions</span></div></div><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Supplier</th><th>Product</th><th>Qty</th><th>Unit Price</th><th>Total</th><th>By</th></tr><?php foreach($purchases as $r): ?><tr><td><?=e(date('d M Y, h:i A',strtotime($r['created_at'])))?></td><td><?=e($r['supplier']??'—')?></td><td><b><?=e($r['product'])?></b></td><td><?=e($r['quantity'])?></td><td>৳<?=number_format((float)$r['unit_price'],2)?></td><td>৳<?=number_format((float)$r['total'],2)?></td><td><?=e($r['user_name'])?></td></tr><?php endforeach; ?><?php if(!$purchases): ?><tr><td colspan="7" class="empty">No purchase history yet.</td></tr><?php endif; ?></table></div></section><?php require __DIR__.'/../../../includes/role_footer.php'; ?>
